// Original, square-pixel game scenery inspired by the red-brick campus buildings.
// All coordinates live on the same 760 × 310 stage, so scenes swap without layout shifts.
const P={sky:'#9bd2d0',skyLight:'#cbe9df',cloud:'#fff3d2',brick:'#a64d3d',brickLight:'#ca7352',brickDark:'#713d3d',cream:'#f0d9ae',gold:'#eebf5a',teal:'#4c7f79',deep:'#273f4a',green:'#397762',leaf:'#58a36c',leafLight:'#91c37a',path:'#caa886',shadow:'#725c57'};
const box=(x,y,w,h,color)=>`<rect x="${x}" y="${y}" width="${w}" height="${h}" fill="${color}"/>`;
const boxes=(items)=>items.map(([x,y,w,h,color])=>box(x,y,w,h,color)).join('');
function cloud(x,y){return `<g class="pixel-cloud">${boxes([[x,y+10,62,12,P.cloud],[x+12,y,33,12,P.cloud],[x+44,y+5,18,8,P.cloud],[x+8,y+22,44,4,'#d6e8d6']])}</g>`}
function sky(night=false){return `${box(0,0,760,310,night?'#172c4d':P.sky)}${night?boxes([[0,0,760,88,'#10223f'],[55,24,3,3,P.cloud],[176,49,3,3,P.cloud],[287,13,2,2,P.cloud],[494,27,3,3,P.cloud],[650,51,2,2,P.cloud],[694,16,3,3,P.cloud],[588,36,20,18,'#f6df9b']]):`${box(0,0,760,76,P.skyLight)}<g class="scene-sun">${box(622,37,36,32,'#ffe2a1')}${box(628,31,24,6,'#ffe2a1')}</g>${cloud(103,34)}${cloud(438,55)}`}`}
function distantBuildings(){let out=box(0,151,760,76,'#729794');for(let i=0;i<9;i++){let x=i*91-20,h=48+(i*23)%38;out+=box(x,190-h,74,h,i%2?'#7fa39e':'#71948f')+box(x,186-h,74,6,'#537b7b');for(let j=0;j<3;j++)out+=box(x+11+j*19,201-h,10,12,'#b5d2ba')}return out}
function brickBuilding(x,y,w,h){let out=boxes([[x+7,y-13,w-14,13,P.brickDark],[x,y,w,h,P.brick],[x,y+8,w,5,P.brickLight],[x,y+h-13,w,13,P.brickDark],[x+6,y+h-8,w-12,5,P.cream]]);for(let row=0;row<8;row++){let yy=y+17+row*14;if(yy>y+h-14)break;for(let xx=x+(row%2?15:7);xx<x+w-9;xx+=34)out+=box(xx,yy,18,2,'#d17d59')}
  const cols=Math.max(3,Math.floor((w-34)/76));for(let row=0;row<2;row++)for(let col=0;col<cols;col++){let xx=x+21+col*((w-42)/cols),yy=y+25+row*51;out+=boxes([[xx-4,yy-5,45,41,P.cream],[xx,yy,37,31,P.deep],[xx+3,yy+3,14,23,'#80b4ad'],[xx+21,yy+3,13,23,'#80b4ad'],[xx+3,yy+3,31,4,'#b3d4c2'],[xx-4,yy+29,45,6,P.brickDark]])}
  return out}
function coveredWalk(x,y,w){let out=boxes([[x,y,w,10,P.brickDark],[x+5,y+10,w-10,5,P.cream]]);for(let xx=x+16;xx<x+w-10;xx+=56)out+=boxes([[xx,y+15,7,66,P.cream],[xx+5,y+18,3,61,'#b79475']]);return out}
function bodhi(x,y,scale=1){let top=`${boxes([[x+36,y+66,16,108,'#6a503e'],[x+45,y+81,7,75,'#8e6747'],[x+19,y+59,21,11,'#6a503e'],[x+53,y+53,28,10,'#6a503e']])}`;const clusters=[[15,45,61,32],[0,61,48,33],[42,36,64,34],[73,54,47,36],[25,17,63,40],[64,15,44,39]];for(const [dx,dy,w,h] of clusters)top+=boxes([[x+dx,y+dy,w,h,P.green],[x+dx+5,y+dy+5,w-12,h-13,P.leaf],[x+dx+9,y+dy+7,16,6,P.leafLight],[x+dx+w-23,y+dy+8,13,7,P.leafLight]]);top+=`<g class="pixel-leaves">${boxes([[x+22,y+62,10,11,P.leafLight],[x+74,y+46,12,10,P.leafLight],[x+92,y+72,9,9,P.leafLight]])}</g>`;return `<g transform="translate(${x*(1-scale)} ${y*(1-scale)}) scale(${scale})">${top}</g>`}
function bicycle(x,y){return `<g transform="translate(${x} ${y})">${boxes([[5,2,20,3,P.deep],[20,4,3,13,P.deep],[41,5,3,13,P.deep],[37,2,14,3,P.deep],[11,17,40,3,P.gold]])}<path d="M12 25h16l-9-15m9 15 16-16m-16 16 12-2" fill="none" stroke="${P.deep}" stroke-width="3"/>${boxes([[4,18,4,4,P.deep],[14,31,4,4,P.deep],[45,31,4,4,P.deep]])}<path d="M10 26h16v4H10zm37 0h16v4H47z" fill="${P.cream}" stroke="${P.deep}" stroke-width="4"/></g>`}
function student(x,y,actor=null,walk='a',color='#8e2535'){
  if(actor&&typeof globalThis.sceneAvatarPixels==='function'){
    const pixels=globalThis.sceneAvatarPixels(actor).map(([px,py,w,h,fill])=>box(px,py,w,h,fill)).join('');
    const role=actor.sceneRole==='companion'?'companion':'player';
    return `<g class="pixel-walker pixel-walker-${walk}" data-scene-role="${role}" data-walker-x="${x+240}"><g transform="translate(${x-6} ${y}) scale(.62 .8)"><g class="pixel-walker-step">${pixels}</g></g></g>`;
  }
  const head=boxes([[x+5,y,14,5,'#292d35'],[x+2,y+5,20,8,'#292d35'],[x+6,y+13,13,10,'#dca37d'],[x+7,y+16,2,2,P.deep],[x+17,y+16,2,2,P.deep]]);
  const body=boxes([[x+3,y+23,20,20,'#fff4db'],[x+4,y+28,19,3,color],[x+4,y+43,19,8,color]]);
  const armLeft=`<g class="pixel-arm-left">${box(x-2,y+25,5,18,'#dca37d')}</g>`;
  const armRight=`<g class="pixel-arm-right">${box(x+23,y+25,5,18,'#dca37d')}</g>`;
  const legLeft=`<g class="pixel-leg-left">${box(x+5,y+50,7,15,P.deep)}${box(x+2,y+62,11,4,'#252936')}</g>`;
  const legRight=`<g class="pixel-leg-right">${box(x+16,y+50,7,15,P.deep)}${box(x+16,y+62,11,4,'#252936')}</g>`;
  return `<g class="pixel-walker pixel-walker-${walk}" data-walker-x="${x+240}"><g class="pixel-walker-step">${head}${body}${armLeft}${armRight}${legLeft}${legRight}</g></g>`;
}
function paving(y){let out=box(0,y,760,310-y,P.path)+box(0,y,760,7,'#a87a6b');for(let row=0;row<4;row++){let yy=y+14+row*23;out+=box(0,yy,760,2,'#b58a76');for(let x=(row%2)*30;x<760;x+=75)out+=box(x,yy+2,2,21,'#b58a76')}return out}
function shrubs(y){let out='';for(let x=0;x<760;x+=25){let h=11+(x*7)%9;out+=boxes([[x,y-h,27,h,P.green],[x+4,y-h-5,16,6,P.leaf],[x+8,y-h-2,6,4,P.leafLight]])}return out}
function campus(actors={}){return `${sky()}${distantBuildings()}${brickBuilding(107,105,545,143)}${boxes([[353,213,64,35,P.deep],[360,220,50,27,'#426363'],[376,220,3,27,P.gold]])}${coveredWalk(57,226,646)}${paving(257)}${bicycle(563,232)}${bodhi(-31,92,.9)}${bodhi(655,94,.78)}${student(150,226,actors.player,'a','#922f3c')}${student(626,230,actors.companion,'b','#356c75')}`}
function sports(actors={}){let out=`${sky()}${distantBuildings()}${brickBuilding(132,131,398,79)}${box(0,217,760,93,'#4d9a68')}${box(0,242,760,68,'#a74648')}`;for(let y=254;y<310;y+=19)out+=box(0,y,760,3,'#e3b07f');out+=boxes([[95,206,570,3,'#e9e9d4'],[95,206,3,38,'#e9e9d4'],[662,206,3,38,'#e9e9d4'],[366,207,3,35,'#e9e9d4'],[572,180,5,43,'#f6eee0'],[657,180,5,43,'#f6eee0'],[572,180,90,5,'#f6eee0']]);out+=`<g class="pixel-sports-ball">${boxes([[600,212,13,13,'#fff4e3'],[603,215,5,5,P.deep]])}</g>`;out+=`${bodhi(-39,105,.62)}${student(111,227,actors.player,'a','#872432')}${student(647,222,actors.companion,'b','#fff1c9')}`;return out}
function indoor(back='#e7d6ba'){return `${box(0,0,760,310,back)}${box(0,0,760,19,P.brickDark)}${box(0,19,760,8,P.gold)}${box(0,213,760,97,'#b88460')}${box(0,215,760,4,'#e6be82')}`}
function library(actors={}){let out=indoor('#e9d7bd');for(let x=28;x<750;x+=136){out+=boxes([[x,43,108,170,P.brickDark],[x+7,48,94,155,'#865044'],[x+6,96,96,6,P.gold],[x+6,149,96,6,P.gold]]);for(let row=0;row<3;row++)for(let j=0;j<9;j++){let xx=x+10+j*10,yy=55+row*53;out+=box(xx,yy,7,36,(j+row)%3?'#3f7168':'#e0aa5d')}}out+=boxes([[195,236,366,12,P.brickDark],[216,246,14,48,P.brickDark],[524,246,14,48,P.brickDark],[322,224,70,13,'#fff1ce'],[373,224,4,13,'#b77c5c'],[480,203,6,32,P.gold],[465,197,35,8,P.gold],[475,193,15,5,'#fff3c6']]);out+=`<g class="pixel-page">${boxes([[324,220,23,4,'#fff8dd'],[325,216,18,3,'#ebd4a5']])}</g>`+student(105,220,actors.player,'a','#8d2537');return out}
function classroom(actors={}){let out=indoor('#e7e3c9');out+=boxes([[57,46,450,153,'#815348'],[64,53,436,139,'#2d625b'],[78,74,180,4,'#9dc3a6'],[89,99,220,3,'#9dc3a6'],[115,125,150,3,'#9dc3a6'],[566,55,138,127,P.cream],[575,64,120,110,'#8db8b2'],[584,73,101,7,'#c8e1ce']]);for(let x=36;x<700;x+=152)out+=boxes([[x,225,111,14,P.brickDark],[x+10,239,9,54,P.brickDark],[x+91,239,9,54,P.brickDark],[x+25,211,50,13,'#f6e6c7']]);out+=`<g class="pixel-chalk">${box(291,125,19,3,'#c9e3c9')}</g>`+student(548,211,actors.player,'a','#8f2635');return out}
function gym(actors={}){let out=indoor('#d6ddc9');out+=boxes([[50,56,180,115,'#8cb4ac'],[58,64,164,100,'#bad7c4'],[353,51,111,71,P.brickDark],[361,59,95,55,'#d6b783'],[508,155,11,76,P.deep],[499,152,30,7,P.cream],[464,122,85,5,P.cream],[0,247,760,6,'#f1d0a0'],[247,215,4,95,P.cream],[500,215,4,95,P.cream]]);for(let x=30;x<760;x+=85)out+=box(x,273,46,3,'#edd09d');out+=`<g class="pixel-gym-ball">${boxes([[574,200,13,13,'#e7aa5d'],[579,200,3,13,'#b27649']])}</g>`+student(155,210,actors.player,'a','#8f2635')+student(614,213,actors.companion,'b','#426d7d');return out}
function gate(actors={}){let out=`${sky()}${distantBuildings()}${brickBuilding(268,134,318,111)}${box(0,241,760,69,'#c9ac89')}`;for(let x=0;x<760;x+=28)out+=boxes([[x,205,5,44,P.green],[x,210,28,5,P.green],[x,234,28,5,P.green]]);out+=boxes([[60,185,83,64,'#e8d9b3'],[52,179,99,10,P.brickDark],[621,189,77,60,'#e8d9b3'],[613,182,93,10,P.brickDark],[332,206,170,42,'#244b47']])+bodhi(678,98,.57)+`<g class="pixel-cycle">${bicycle(59,244)}</g>`+student(224,231,actors.player,'a','#8d2535');return out}
function garden(){let out=`${sky()}${distantBuildings()}${box(0,208,760,102,'#73a87f')}${box(177,247,411,63,'#67ada9')}${box(191,253,385,49,'#91c9b4')}${box(0,282,760,28,'#b3a078')}`;out+=boxes([[310,165,155,7,P.brickDark],[325,154,125,10,P.brick],[344,146,87,9,P.brickDark],[330,172,8,77,P.cream],[438,172,8,77,P.cream],[335,196,107,7,P.gold],[342,204,95,36,'#f1dec0']]);out+=bodhi(30,109,.72)+bodhi(612,100,.7);for(let x=205;x<575;x+=63)out+=boxes([[x,268,13,4,'#43877e'],[x+4,263,5,6,'#e8b6bc']]);out+=`<g class="pixel-water">${boxes([[226,276,32,3,'#d6ead0'],[472,261,29,3,'#d6ead0'],[524,284,23,3,'#d6ead0']])}</g>`;return out}
function shopping(actors={}){let out=`${sky()}${distantBuildings()}${boxes([[69,109,629,149,'#e7d6b6'],[61,100,645,20,P.brickDark],[79,121,609,12,P.gold],[95,141,565,95,'#7baab2'],[95,141,565,7,P.cream],[95,229,565,10,P.brickDark]])}`;for(let x=106;x<640;x+=107)out+=boxes([[x,140,8,96,P.cream],[x+8,194,99,4,P.cream],[x+25,157,61,28,'#a7cfc5']]);out+=`<g class="pixel-door-left">${box(361,177,22,52,'#b8ddd3')}</g><g class="pixel-door-right">${box(385,177,22,52,'#b8ddd3')}</g>`;out+=paving(258)+student(114,232,actors.player,'a','#8d2535')+student(637,232,actors.companion,'b','#356c75');return out}
function market(actors={}){let out=`${sky(true)}${distantBuildings()}${box(0,238,760,72,'#6b6272')}`;for(let x=52;x<745;x+=184){out+=boxes([[x,155,152,11,P.brickDark],[x+8,166,136,11,P.gold],[x+15,177,120,80,'#bd6644'],[x+16,210,118,44,'#67434a'],[x+31,196,80,12,'#e4b573'],[x+12,169,4,82,P.deep],[x+67,129,4,26,P.gold],[x+136,169,4,82,P.deep]]);out+=`<g class="pixel-lantern">${boxes([[x+61,128,16,15,'#ffe2a2'],[x+64,131,10,9,'#fff4c7']])}</g>`;for(let j=0;j<5;j++)out+=box(x+15+j*25,181,17,9,j%2?P.cream:'#96384a')}out+=paving(265)+student(92,221,actors.player,'a','#f0d9ae')+student(670,220,actors.companion,'b','#8f2635');return out}
const SCENE_ART={campus,sports,gym,library,classroom,shopping,market,gate,garden};
function sceneArt(kind,actors={}){
  const indoorScene=['gym','library','classroom'].includes(kind),night=kind==='market';
  const sides=indoorScene
    ? `${box(0,0,1240,310,'#e7d7bc')}${box(0,0,1240,24,P.brickDark)}${box(0,218,1240,92,'#b88460')}${boxes([[32,56,150,157,P.brickDark],[1058,56,150,157,P.brickDark],[56,79,102,107,'#678a78'],[1082,79,102,107,'#678a78']])}`
    : `${box(0,0,1240,310,night?'#172c4d':P.skyLight)}${box(0,157,1240,101,night?'#405c69':'#729794')}${box(0,258,1240,52,night?'#6b6272':P.path)}${night?'':`${bodhi(46,96,.8)}${bodhi(1087,96,.8)}`}`;
  let rain='';
  for(let row=0;row<11;row++)for(let col=0;col<31;col++)if((row*7+col*11)%5===0)rain+=box(col*42+(row%3)*12,row*33-10,3,12,'#e7f4ee');
  return `${sides}<g transform="translate(240 0)">${(SCENE_ART[kind]||SCENE_ART.campus)(actors)}</g><g class="pixel-rain">${rain}</g>`;
}
globalThis.sceneArt=sceneArt;
